### G1894
Lines to replace: L159–L182
Kind: review
Task: Check that `validate` behaves like the original `scope.validate`; fix it if it does not.
The original AngularJS function:
```js
        scope.validate = function () {
            try {
                if (scope.validateContent) {
                    if (scope.contentType == types.contentType.JSON.value) {
                        angular.fromJson(scope.contentBody);
                    }
                }
                return true;
            } catch (e) {
                if (!scope.hideErrorToast) {
                    var details = utils.parseException(e);
                    var errorInfo = 'Error:';
                    if (details.name) {
                        errorInfo += ' ' + details.name + ':';
                    }
                    if (details.message) {
                        errorInfo += ' ' + details.message;
                    }
                    scope.showError(errorInfo);
                }
                return false;
            }
        };
```
